# Living fish. With over 35,000 species this follows the well-known-names rule: famous sharks and
# rays, the coelacanth and lungfish, and well-known bony fish, with relatives mentioned. Ocean
# ranges are drawn as sea boxes with land cut out, so they are approximate.


def C(*names, **clip):
    return {'countries': list(names), **clip}


def part(country, lon0, lat0, lon1, lat1):
    return {'country': country, 'bbox': [lon0, lat0, lon1, lat1]}


def sea(lon0, lat0, lon1, lat1):
    return {'sea': [lon0, lat0, lon1, lat1]}


